styleTag:
* {
  box-sizing: border-box
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent
}

body {
  font-family: Arial, Helvetica, sans-serif;
  --u: 1px;
  --bg: {background_color};
  --border: {border_color};
  --glow: {glow_color};
  --label: {label_color};
  --text: {destination_color};
  --label-size: {label_font_size};
  --destination-size: {destination_font_size};
  --road: {road_color};
  --opacity: .50;
  --glow-opacity: .24;
  --road-duration: .62s;
  --wheel-duration: .38s;
  --bounce-duration: .95s;
  --trail-duration: .82s
}

.card {
  position: absolute;
  left: calc(8 * var(--u));
  top: calc(8 * var(--u));
  bottom: calc(8 * var(--u));
  width: var(--panel-width, calc(100% - 16 * var(--u)));
  display: flex;
  align-items: center;
  gap: calc(8 * var(--u));
  padding: calc(12 * var(--u)) calc(18 * var(--u));
  border: calc(1.4 * var(--u)) solid var(--border);
  border-radius: calc(17 * var(--u));
  isolation: isolate;
  box-shadow: 0 0 calc(9 * var(--u)) color-mix(in srgb, var(--glow) calc(var(--glow-opacity) * 100%), transparent), inset 0 0 calc(12 * var(--u)) color-mix(in srgb, var(--glow) 7%, transparent);
  overflow: hidden
}

.card:before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: var(--bg);
  opacity: var(--opacity)
}

.copy {
  flex: 0 0 auto;
  min-width: 0;
  position: relative;
  z-index: 2
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: calc(7 * var(--u));
  color: var(--label);
  font-size: calc(var(--label-size) * var(--u));
  line-height: 1.2;
  font-weight: 700;
  letter-spacing: calc(2 * var(--u));
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  margin-bottom: calc(7 * var(--u))
}

.dot {
  width: calc(5 * var(--u));
  height: calc(5 * var(--u));
  background: var(--label);
  border-radius: 50%;
  flex: none;
  box-shadow: 0 0 calc(6 * var(--u)) var(--glow)
}

.destination {
  font-size: calc(var(--destination-size) * var(--u));
  font-weight: 800;
  letter-spacing: calc(-.8 * var(--u));
  color: var(--text);
  line-height: 1.06;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 calc(1 * var(--u)) calc(5 * var(--u)) #0008
}

.scene {
  position: relative;
  flex: 0 0 var(--scene-width, 42%);
  height: 100%;
  min-width: 0;
  overflow: hidden
}

.car-wrap {
  position: absolute;
  inset: 3% -1% 9% 4%;
  animation: suspension var(--bounce-duration) ease-in-out infinite
}

.car {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible
}

.wheel-spin {
  transform-box: view-box;
  transform-origin: 0 0;
  animation: wheel var(--wheel-duration) linear infinite
}

.road {
  position: absolute;
  top: 3%;
  left: 4%;
  width: 97%;
  height: 97%;
  filter: brightness(4);
  pointer-events: none;
}

.speedlines {
  position: absolute;
  left: 0;
  top: 29%;
  width: 39%;
  height: 45%;
  mask-image: linear-gradient(90deg, transparent, #000 35%, transparent)
}

.speedlines i {
  position: absolute;
  left: 30%;
  width: 62%;
  height: calc(1 * var(--u));
  background: var(--road);
  opacity: 0;
  animation: trail var(--trail-duration) linear infinite
}

.speedlines i:nth-child(1) {
  top: 10%;
  animation-delay: -.1s
}

.speedlines i:nth-child(2) {
  top: 50%;
  width: 43%;
  animation-delay: -.4s
}

.speedlines i:nth-child(3) {
  top: 83%;
  animation-delay: -.65s
}

.paused * {
  animation-play-state: paused !important
}

.hide-road .road {
  display: none
}

.compact .card {
  right: calc(8 * var(--u));
  width: auto;
  flex-direction: column;
  gap: 0;
  padding: calc(13 * var(--u))
}

.compact .copy {
  flex: 0 0 45%;
  width: 100%;
  display: flex;
  justify-content: center;
  flex-direction: column
}

.compact .scene {
  flex: 1;
  width: 100%;
  height: 55%
}

.compact .destination {
  font-size: calc(var(--destination-size) * .933333 * var(--u))
}

@keyframes suspension {

  0%,
  100% {
    transform: translateY(0) rotate(-.07deg)
  }

  25% {
    transform: translateY(calc(-.3 * var(--u))) rotate(.05deg)
  }

  55% {
    transform: translateY(calc(.22 * var(--u))) rotate(-.03deg)
  }

  80% {
    transform: translateY(calc(-.18 * var(--u))) rotate(.025deg)
  }
}

@keyframes wheel {
  to {
    transform: rotate(360deg)
  }
}



@keyframes trail {
  0% {
    transform: translateX(20%);
    opacity: 0
  }

  25% {
    opacity: .22
  }

  100% {
    transform: translateX(-100%);
    opacity: 0
  }
}

scriptTag:
var settings = document.getElementById('settings');
var destinationNode = document.getElementById('destination');
function fitDestination() {
  var u = parseFloat(document.body.style.getPropertyValue('--u')) || 1;
  var compact = document.body.classList.contains('compact');
  var controls = getComputedStyle(document.body);
  var base = parseFloat(controls.getPropertyValue('--destination-size')) * (compact ? 28 / 30 : 1);
  var labelBase = parseFloat(controls.getPropertyValue('--label-size'));
  var heading = document.querySelector('.eyebrow');
  var copy = document.querySelector('.copy');
  var panelStyle = getComputedStyle(document.getElementById('card'));
  var textHeight = compact ? copy.clientHeight : document.getElementById('card').clientHeight - parseFloat(panelStyle.paddingTop) - parseFloat(panelStyle.paddingBottom);
  var heightScale = Math.min(1, Math.max(.1, (textHeight - 7 * u) / ((labelBase * 1.2 + base * 1.06) * u)));
  base *= heightScale;
  heading.style.fontSize = (labelBase * u * heightScale) + 'px';
  destinationNode.style.fontSize = (base * u) + 'px';
  if (document.body.classList.contains('compact')) {
    copy.style.removeProperty('width');
  } else {
    var range = document.createRange();
    range.selectNodeContents(destinationNode);
    var textWidth = range.getBoundingClientRect().width;
    range.selectNodeContents(document.getElementById('travelLabel'));
    var headingWidth = range.getBoundingClientRect().width + 12 * u;
    var card = document.getElementById('card');
    var style = getComputedStyle(card);
    var padding = parseFloat(style.paddingLeft) + parseFloat(style.paddingRight);
    var borders = parseFloat(style.borderLeftWidth) + parseFloat(style.borderRightWidth);
    var gap = parseFloat(style.columnGap);
    var maxPanelWidth = document.documentElement.clientWidth - 16 * u;
    var maxContentWidth = Math.max(1, maxPanelWidth - padding - borders);
    var sceneHeight = card.clientHeight - parseFloat(style.paddingTop) - parseFloat(style.paddingBottom);
    var sceneWidth = Math.min(maxContentWidth * .5, sceneHeight * .88 * 2050 / 990 / .97);
    var available = Math.max(1, maxContentWidth - sceneWidth - gap);
    var copyWidth = Math.max(1, Math.min(Math.ceil(Math.max(textWidth, headingWidth)) + 1, available));
    copy.style.width = copyWidth + 'px';
    document.body.style.setProperty('--scene-width', sceneWidth + 'px');
    document.body.style.setProperty('--panel-width', Math.min(maxPanelWidth, copyWidth + sceneWidth + gap + padding + borders) + 'px');
  }
  if (destinationNode.scrollWidth > destinationNode.clientWidth) destinationNode.style.fontSize = Math.max(Math.min(12, base) * u, base * u * destinationNode.clientWidth / destinationNode.scrollWidth * .97) + 'px';
}
function resizeWidget() {
  var w = document.documentElement.clientWidth;
  var h = document.documentElement.clientHeight;
  var compact = w / Math.max(h, 1) < 2.2;
  document.body.classList.toggle('compact', compact);
  document.body.style.setProperty('--u', Math.max(.05, compact ? Math.min(w / 300, h / 200) : Math.min(w / 300, h / 130)) + 'px');
  fitDestination();
}
function onLiveVariableUpdate(name, value) {
  var colors = { background_color: '--bg', border_color: '--border', glow_color: '--glow', label_color: '--label', destination_color: '--text', road_color: '--road' };
  if (colors[name]) document.body.style.setProperty(colors[name], value);
  if (name === 'label_font_size' || name === 'destination_font_size') {
    document.body.style.setProperty(name === 'label_font_size' ? '--label-size' : '--destination-size', Math.max(6, Math.min(64, Number(value))));
    fitDestination();
  }
  if (name === 'destination') { destinationNode.textContent = value; fitDestination(); }
  if (name === 'travel_label') { document.getElementById('travelLabel').textContent = value; fitDestination(); }
  if (name === 'background_opacity') document.body.style.setProperty('--opacity', Math.max(0, Math.min(100, Number(value))) / 100);
  if (name === 'glow_strength') document.body.style.setProperty('--glow-opacity', Math.max(0, Math.min(100, Number(value))) / 100);
  if (name === 'animation_speed') {
    var speed = Math.max(.25, Math.min(3, Number(value)));
    document.body.style.setProperty('--road-duration', (.62 / speed) + 's');
    document.body.style.setProperty('--wheel-duration', (.38 / speed) + 's');
    document.body.style.setProperty('--bounce-duration', (.95 / speed) + 's');
    document.body.style.setProperty('--trail-duration', (.82 / speed) + 's');
  }
  if (name === 'animate') document.body.classList.toggle('paused', String(value) === 'false');
  if (name === 'show_road') document.body.classList.toggle('hide-road', String(value) === 'false');
}
onLiveVariableUpdate('background_opacity', settings.dataset.opacity);
onLiveVariableUpdate('glow_strength', settings.dataset.glow);
onLiveVariableUpdate('animation_speed', settings.dataset.speed);
onLiveVariableUpdate('animate', settings.dataset.motion);
onLiveVariableUpdate('show_road', settings.dataset.road);
resizeWidget();
var widgetResizeObserver = new ResizeObserver(resizeWidget);
widgetResizeObserver.observe(document.documentElement);
window.addEventListener('beforeunload', function () { widgetResizeObserver.disconnect(); });

// Align the complete driving scene with the destination row in wide layouts.
var fitDestinationBeforeSceneAlignment = fitDestination;
fitDestination = function () {
  fitDestinationBeforeSceneAlignment();
  var scene = document.querySelector('.scene');
  scene.style.removeProperty('transform');
  if (document.body.classList.contains('compact')) return;
  var destinationBounds = destinationNode.getBoundingClientRect();
  var sceneBounds = scene.getBoundingClientRect();
  var offset = destinationBounds.top + destinationBounds.height / 2 - sceneBounds.top - sceneBounds.height / 2;
  scene.style.transform = 'translateY(' + offset + 'px)';
};
fitDestination();

// Paint the original road directly into a canvas instead of masked SVG.
var roadCanvas = document.getElementById('roadCanvas');
var roadContext = roadCanvas.getContext('2d');
var roadPhase = 0;
var roadFrame = 0;
var lastRoadTime = 0;
function drawRoad() {
  var width = roadCanvas.clientWidth;
  var height = roadCanvas.clientHeight;
  if (!width || !height) return;
  var dpr = window.devicePixelRatio || 1;
  var pixelWidth = Math.max(1, Math.round(width * dpr));
  var pixelHeight = Math.max(1, Math.round(height * dpr));
  if (roadCanvas.width !== pixelWidth || roadCanvas.height !== pixelHeight) {
    roadCanvas.width = pixelWidth;
    roadCanvas.height = pixelHeight;
  }
  roadContext.setTransform(dpr, 0, 0, dpr, 0, 0);
  roadContext.clearRect(0, 0, width, height);
  var svgHeight = height * 88 / 97;
  var scale = Math.min(width / 2050, svgHeight / 990);
  var offsetY = (svgHeight - 990 * scale) / 2;
  roadContext.save();
  roadContext.translate(-235 * scale, offsetY - 380 * scale);
  roadContext.scale(scale, scale);
  roadContext.transform(1, .077, -.58, .22, 0, 1240);
  roadContext.strokeStyle = getComputedStyle(document.body).getPropertyValue('--road').trim();
  roadContext.globalAlpha = .62 * .19;
  roadContext.lineWidth = 5;
  roadContext.setLineDash([]);
  roadContext.beginPath();
  roadContext.moveTo(-1000, -220);
  roadContext.lineTo(3500, -220);
  roadContext.stroke();
  roadContext.globalAlpha = 1;
  roadContext.lineWidth = 32;
  roadContext.setLineDash([250, 220]);
  roadContext.lineDashOffset = roadPhase * 470;
  roadContext.beginPath();
  roadContext.moveTo(-1000, 0);
  roadContext.lineTo(3500, 0);
  roadContext.stroke();
  roadContext.restore();
  var fade = roadContext.createLinearGradient(0, 0, width, 0);
  fade.addColorStop(0, 'rgba(0,0,0,0)');
  fade.addColorStop(.14, 'rgba(0,0,0,1)');
  fade.addColorStop(.85, 'rgba(0,0,0,1)');
  fade.addColorStop(1, 'rgba(0,0,0,0)');
  roadContext.globalCompositeOperation = 'destination-in';
  roadContext.fillStyle = fade;
  roadContext.fillRect(0, 0, width, height);
  roadContext.globalCompositeOperation = 'source-over';
}
function animateRoad(now) {
  if (now - lastRoadTime >= 30) {
    var elapsed = lastRoadTime ? Math.min(now - lastRoadTime, 100) / 1000 : 0;
    lastRoadTime = now;
    if (!document.body.classList.contains('paused')) {
      var duration = parseFloat(getComputedStyle(document.body).getPropertyValue('--road-duration')) || .62;
      roadPhase = (roadPhase + elapsed / duration) % 1;
    }
    drawRoad();
  }
  roadFrame = requestAnimationFrame(animateRoad);
}
drawRoad();
roadFrame = requestAnimationFrame(animateRoad);
window.addEventListener('beforeunload', function () { cancelAnimationFrame(roadFrame); });
